package com.gerenciadorrural.modules.herd.infrastructure;
import com.gerenciadorrural.modules.herd.domain.*; import com.gerenciadorrural.shared.tenancy.TenantId; import java.util.*; import org.springframework.jdbc.core.namedparam.*; import org.springframework.stereotype.Repository;
@Repository public class JdbcHerdAnimalQueryRepository implements HerdAnimalQueryRepository { private final NamedParameterJdbcTemplate jdbc; public JdbcHerdAnimalQueryRepository(NamedParameterJdbcTemplate jdbc){this.jdbc=jdbc;} public HerdAnimalPage list(TenantId tenantId,UUID farmId,HerdAnimalQuery q){var p=new MapSqlParameterSource().addValue("tenantId",tenantId.value()).addValue("farmId",farmId).addValue("limit",q.size()).addValue("offset",q.page()*q.size());var where=new StringBuilder(" where a.tenant_id=:tenantId and a.farm_id=:farmId");if(q.sex()!=null){where.append(" and a.sex=:sex");p.addValue("sex",q.sex().name());}if(q.status()!=null){where.append(" and a.status=:status");p.addValue("status",q.status().name());}if(q.search()!=null){where.append(" and (lower(a.identification) like :search escape '\\' or lower(coalesce(a.name,'')) like :search escape '\\')");p.addValue("search","%"+escape(q.search().toLowerCase(Locale.ROOT))+"%");}var items=jdbc.query("select a.id,a.identification,a.name,a.sex,a.birth_date,a.status,a.version from app.animals a"+where+" order by lower(btrim(a.identification)),a.id limit :limit offset :offset",p,(r,i)->new HerdAnimalSummary(r.getObject("id",UUID.class),r.getString("identification"),r.getString("name"),HerdAnimalSex.valueOf(r.getString("sex")),r.getObject("birth_date",java.time.LocalDate.class),HerdAnimalStatus.valueOf(r.getString("status")),r.getLong("version")));Long total=jdbc.queryForObject("select count(*) from app.animals a"+where,p,Long.class);return new HerdAnimalPage(items,q.page(),q.size(),total==null?0:total);} private static String escape(String value){return value.replace("\\","\\\\").replace("%","\\%").replace("_","\\_");} }
